export function roleLabel(role: "admin" | "member" | "unknown") {
  switch (role) {
    case "admin":
      return "Admin";
    case "member":
      return "Member";
    default:
      return "Unknown";
  }
}

export function statusLabel(status: "active" | "inactive" | "unknown") {
  switch (status) {
    case "active":
      return "Active";
    case "inactive":
      return "Inactive";
    default:
      return "Unknown";
  }
}
